INSERT INTO qa_pairs (id, question, answer, answer_brief, source_doc_id, category, tags, status, confidence, multi_dimensional, created_at, updated_at) VALUES
('QA20260701001', 'J7卡车DPF灯亮了怎么办？还能继续开吗？', '当DPF（颗粒捕集器）报警灯亮起时，说明DPF中积碳已达到需要进行再生的程度。建议处理方案：1. 如果车辆动力正常，可以继续行驶但应尽快进行DPF再生；2. 降低车速至80km/h以下；3. 前往最近的服务站进行强制再生；4. 如果动力明显下降或伴有发动机故障灯，建议立即靠边停车并联系客服救援。不建议长期无视DPF报警继续行驶，否则可能导致DPF堵塞损坏，维修费用高达1-2万元。', 'DPF灯亮应尽快进行再生处理，降低车速前往服务站，不可长期无视。', 'DOC20260702003', '故障处理', '["DPF","颗粒捕集器","再生","报警灯","J7"]', 'PUBLISHED', 0.9520,
 '{"relatedIssues":["DPF堵塞","发动机故障灯","排放系统"],"vehicleModels":["J7","J6P","JH6"],"difficulty":"中等","estimatedTime":"30分钟-2小时"}',
 '2026-06-20 09:30:00', '2026-07-01 10:00:00'),

('QA20260701002', '解放卡车10万公里大保养需要做哪些项目？费用多少？', '解放卡车10万公里大保养属于重要保养节点，主要包括以下项目：1. 更换发动机机油和机油滤芯；2. 更换柴油滤芯（粗滤+精滤）；3. 更换空气滤芯；4. 更换变速箱油和后桥齿轮油；5. 检查并调整气门间隙；6. 检查刹车片磨损情况；7. 检查转向系统和悬挂系统；8. 检查T-Box终端工作状态。全套费用约3500-5000元（因车型和地区略有差异），保养时间约3-4小时。建议通过APP或客服电话提前3天预约。', '10万公里保养包含机油三滤、变速箱油、后桥油、气门间隙等，费用3500-5000元，耗时3-4小时。', 'DOC20260702004', '保养维修', '["保养","10万公里","大保养","费用","保养项目"]', 'PUBLISHED', 0.9380,
 '{"relatedIssues":["保养周期","保养费用","服务站预约"],"vehicleModels":["J7","J6P","JH6","鹰途"],"difficulty":"简单","estimatedTime":"3-4小时"}',
 '2026-06-22 14:00:00', '2026-07-02 08:30:00'),

('QA20260702003', 'T-Box设备离线了怎么恢复？', 'T-Box离线恢复步骤：1. 首先确认车辆是否在地下室、隧道等信号弱区域，移动到开阔地带；2. 检查车辆电瓶电压是否正常（应大于24V）；3. 熄火状态下等待5分钟后重新通电；4. 通过车队管理平台发送远程重启指令；5. 如果以上方法无效，可能需要远程固件升级或服务站检测硬件。常见原因：SIM卡欠费、天线松动、固件版本过低、电源模块故障。24小时客服热线可协助远程诊断。', 'T-Box离线先确认信号和电源，可远程重启或升级固件，无法恢复需服务站检测。', 'DOC20260701002', '终端设备', '["T-Box","离线","远程诊断","固件升级","终端"]', 'PUBLISHED', 0.9210,
 '{"relatedIssues":["T-Box安装","SIM卡","GPS定位"],"vehicleModels":["全系"],"difficulty":"中等","estimatedTime":"10-30分钟"}',
 '2026-06-25 10:00:00', '2026-07-03 09:00:00'),

('QA20260703004', '如何通过车队管理平台查看车辆油耗分析？', '油耗分析操作步骤：1. 登录车队管理平台（PC端或APP端）；2. 在左侧导航栏选择"油耗管理"模块；3. 选择查看维度：单车油耗/车队油耗/月度趋势；4. 选择时间范围（支持日/周/月/自定义）；5. 查看百公里油耗曲线图、怠速油耗占比、急加速/急减速统计等；6. 支持导出油耗报表（PDF/Excel格式）。平台还提供异常油耗自动告警功能，当单车油耗偏离车队平均值20%以上时会自动通知。', '登录平台→油耗管理→选择车辆和时间→查看油耗曲线和统计分析→可导出报表。', 'DOC20260703005', '平台操作', '["油耗分析","车队管理","平台操作","油耗统计"]', 'PUBLISHED', 0.8950,
 '{"relatedIssues":["轨迹回放","驾驶行为分析","报表导出"],"vehicleModels":["全系"],"difficulty":"简单","estimatedTime":"2分钟"}',
 '2026-06-28 15:00:00', '2026-07-04 11:00:00'),

('QA20260704005', '国六SCR系统故障怎么排查？尿素消耗快正常吗？', 'SCR系统故障排查步骤：1. 检查尿素液位是否充足（低于10%会触发报警）；2. 检查尿素质量是否符合GB29518标准（使用劣质尿素会导致喷嘴堵塞）；3. 读取故障码判断具体问题（常见故障码：P203B尿素压力传感器故障、P2047尿素喷嘴堵塞、P20E8尿素液位传感器故障）；4. 检查尿素管路是否泄漏或结晶。尿素正常消耗量为柴油消耗量的3%-5%，即每100L柴油消耗3-5L尿素。如果消耗明显偏高，可能原因：1. 排温传感器故障导致过量喷射；2. 尿素喷嘴雾化不良；3. SCR催化器效率下降。建议定期到服务站进行SCR系统检测。', 'SCR系统故障先检查尿素液位和质量，读取故障码定位问题。尿素正常消耗为柴油的3%-5%。', 'DOC20260704006', '排放系统', '["SCR","尿素","国六","排放","故障排查"]', 'PUBLISHED', 0.9080,
 '{"relatedIssues":["DPF再生","排放超标","尿素"],"vehicleModels":["J7国六","J6P国六"],"difficulty":"较高","estimatedTime":"1-3小时"}',
 '2026-07-02 09:00:00', '2026-07-05 14:00:00'),

('QA20260705006', '车队管理系统如何批量导入车辆？', '批量导入车辆流程：1. 准备车辆信息Excel模板（包含：VIN码、车牌号、T-Box ICCID、车辆型号、所属车队）；2. 登录车队管理平台→车辆管理→批量导入→下载模板→填写数据→上传文件；3. 系统自动校验VIN码和ICCID有效性；4. 校验通过后一键导入，系统自动下发配置到T-Box终端；5. 等待T-Box上线验证数据。注意事项：VIN码为17位，ICCID为20位，确保数据准确；单次最多导入500台车；导入后需1-2小时完成全部激活。如有问题可联系技术支持。', '下载Excel模板→填写VIN/ICCID→上传→系统自动校验→一键导入→等待激活。', 'DOC20260703005', '平台操作', '["批量导入","车辆管理","车队","平台操作"]', 'PUBLISHED', 0.8860,
 '{"relatedIssues":["车辆注册","ICCID管理","平台配置"],"vehicleModels":["全系"],"difficulty":"简单","estimatedTime":"30分钟"}',
 '2026-07-05 16:00:00', '2026-07-06 10:00:00'),

('QA20260706007', '夏季高温天气解放卡车需要注意哪些保养事项？', '夏季高温保养要点：1. 空调系统：检查制冷剂压力，清洗冷凝器散热片，确保制冷效果；2. 冷却系统：检查冷却液液位和冰点（建议-35℃冷却液），清洗水箱散热器外部杂物；3. 轮胎：适当降低胎压（比标准低5%-10%），检查轮胎磨损和老化裂纹；4. 电瓶：检查电瓶液位（免维护电瓶除外），清洁接线柱氧化物；5. 线路防火：检查发动机舱线路老化情况，防止高温自燃；6. 油品：使用夏季标号机油（如15W-40），确保高温下润滑性能；7. 驾驶习惯：避免长时间高转速行驶，注意观察水温表，定时停车散热。', '夏季保养重点：空调、冷却液、轮胎气压、电瓶、线路检查、夏季机油、避免高温长时间行驶。', 'DOC20260705007', '季节性文档', '["夏季保养","高温","空调","冷却液","轮胎"]', 'PUBLISHED', 0.8720,
 '{"relatedIssues":["冬季保养","雨季行车","保养周期"],"vehicleModels":["全系"],"difficulty":"简单","estimatedTime":"半天"}',
 '2026-07-06 08:00:00', '2026-07-07 09:00:00'),

('QA20260707008', '车辆ECU通讯丢失怎么办？什么原因导致的？', 'ECU通讯丢失故障处理：1. 首先检查电瓶电压是否正常（24V系统电压应大于22V）；2. 检查ECU供电保险丝是否熔断（保险盒位置参见用户手册）；3. 检查电瓶负极搭铁线是否松动或腐蚀；4. 检查CAN总线终端电阻（正常为60Ω±10%）；5. 如果以上都正常，可能是ECU本体故障。常见原因：电瓶老化亏电、保险丝熔断、线路接触不良、电瓶柱氧化、ECU进水或受潮。紧急处理时可尝试断开电瓶负极1分钟后重新连接，看能否恢复正常。如果仍无法解决，需联系服务站进行专业诊断。', '检查电瓶电压→保险丝→搭铁线→CAN总线电阻→尝试断电重启→仍不行联系服务站。', 'DOC20260706008', '故障处理', '["ECU","通讯故障","电瓶","保险丝","CAN总线"]', 'PUBLISHED', 0.9140,
 '{"relatedIssues":["发动机熄火","仪表盘报警","电路故障"],"vehicleModels":["全系"],"difficulty":"中等","estimatedTime":"30分钟-2小时"}',
 '2026-07-08 11:00:00', '2026-07-08 16:00:00');

