INSERT INTO iterations (id, source_session_id, session_summary, extracted_question, extracted_answer, existing_qa_id, comparison, created_at, status) VALUES
('IT20260701001', 'SE20260701001', '客户张建国反馈J7卡车DPF灯亮和发动机故障灯亮，动力有所下降。客服李娜建议降低车速前往长春服务站做DPF再生，并协助预约了服务站。问题最终通过DPF强制再生解决。', 'J7卡车DPF灯亮且动力下降，应该怎么应急处理？', 'DPF灯亮伴有动力下降时，建议：1. 降低车速至80km/h以下；2. 避免急加速和高转速；3. 尽快前往最近的服务站进行DPF强制再生；4. 不要长时间继续行驶以免损坏DPF总成。DPF再生费用约1000-2000元，更换总成需12000元以上。', 'QA20260701001', '{"similarity":0.92,"newInfo":["动力下降情况下的应急建议","DPF再生与更换费用对比"],"improvement":"原问答未强调动力下降时的紧急性，建议补充费用对比信息"}', '2026-07-01 14:00:00', 'PROCESSED'),

('IT20260702002', 'SE20260703003', '客户李国强反馈车队鹰途T-Box连续两天离线。客服刘芳通过远程诊断发现是固件版本过低导致，执行远程升级后设备恢复正常。', 'T-Box连续多天离线，远程升级固件能解决吗？', 'T-Box长时间离线可能是固件版本问题。V3终端固件版本低于4.2.1的设备存在已知的掉线bug，可通过平台远程推送固件升级解决。升级流程：1. 确认设备ICCID；2. 在平台设备管理中发起远程升级；3. 等待设备重启（约10分钟）；4. 验证数据上报。如果升级后仍无法解决，需服务站现场检测。', 'QA20260702003', '{"similarity":0.88,"newInfo":["固件版本V4.2.1的已知bug","远程升级等待时间约10分钟"],"improvement":"原问答未提及特定版本号的已知问题，建议补充版本相关信息"}', '2026-07-03 10:30:00', 'PROCESSED'),

('IT20260703003', 'SE20260704004', '客户赵大勇J6P自卸车突然熄火无法启动。客服李娜通过远程诊断分析故障码U0100（ECU通讯丢失），指导客户检查电瓶和保险丝。最终发现是电瓶负极松动导致。', 'J6P突然熄火打不着，故障码U0100，应该检查哪里？', '故障码U0100表示ECU通讯丢失，排查步骤：1. 优先检查电瓶负极线是否松动（最常见原因）；2. 检查ECU供电保险丝；3. 检查电瓶电压；4. 尝试断电重启：断开电瓶负极，等待1分钟后重新连接。工程车辆由于作业震动大，电瓶桩头松动是比较常见的故障原因。', '', '{"similarity":0.75,"newInfo":["工程车辆电瓶松动的常见性","故障码U0100的快速排查法"],"improvement":"可新增一条针对工程车辆电瓶检查的问答"}', '2026-07-04 17:00:00', 'NEW_QA_CREATED'),

('IT20260704004', 'SE20260705005', '沈阳恒通物流车队长孙明辉咨询35台解放J7接入车队管理系统。客服陈静介绍了批量导入流程、费用方案和合同签订。最终成功签约企业版套餐。', '车队批量接入智能车队管理系统的完整流程是什么？', '批量接入流程：1. 提供VIN清单和T-Box ICCID清单；2. 后台批量注册车辆信息；3. 远程推送配置参数到每台T-Box；4. 等待设备上线验证（约1-2小时）。企业版费用：每台车600元/年，含实时定位、轨迹回放、油耗分析、故障诊断等全功能。35台车以上可享批量折扣。', 'QA20260705006', '{"similarity":0.82,"newInfo":["企业版定价600元/年/台","35台以上的批量折扣","完整迁移流程含时间节点"],"improvement":"原问答缺少费用和折扣信息，建议补充商务信息"}', '2026-07-05 13:00:00', 'PROCESSED'),

('IT20260705005', 'SE20260708008', '客户郑伟明查询DPF总成配件，客服李娜提供了配件号、价格、库存和质保政策。同时建议了清洗再生的替代方案，帮客户节省了费用。', 'DPF总成更换与清洗再生该如何选择？费用差多少？', 'DPF故障处理有两种路径：1. DPF清洗再生：适用于轻度至中度堵塞，费用约1500元，耗时半天，成功率约80%；2. DPF总成更换：适用于严重堵塞或已损坏，费用约12800元（原厂），质保12个月/10万公里。建议先尝试清洗再生，无效再考虑更换。', '', '{"similarity":0.70,"newInfo":["DPF清洗再生的成功率约80%","清洗与更换的费用对比（1500 vs 12800）","选择建议的标准"],"improvement":"建议新建一条DPF清洗vs更换的对比问答"}', '2026-07-08 16:30:00', 'PENDING');
